  if (indexedDB.databases) {
    const dbs = await indexedDB.databases();
    for (const db of dbs) {
      indexedDB.deleteDatabase(db.name);
    }
  }
  // clear cache storage
  if (window.caches) {
    const keys = await caches.keys();
    for (const k of keys) await caches.delete(k);
  }
  return 'cleared';
}

